    def inb(x, y):
        return 0 <= x < w and 0 <= y < h

    def count_adj(cset, x, y):
        c = 0
        for dx, dy in neigh8:
            if dx == 0 and dy == 0:
                continue
            nx, ny = x + dx, y + dy
            if inb(nx, ny) and (nx, ny) in cset:
                c += 1
        return c

    def cell_score(nx, ny):
        if not inb(nx, ny) or (nx, ny) in obstacles:
            return -10**9
        if (nx, ny) in self_cells:
            return 3.0
        d_opp = abs(nx - ox) + abs(ny - oy)
